    const res = await wixRequest<Raw>(`${BASE}/${campaignId}/metrics`, { method: "GET" });
    return (res?.currencyMetricsList ?? []) as Raw[];
  } catch {
    return null; // unavailable is not a successfully-read zero total
  }
